/* ProcessCircle Widget Styles - Carbon Design System */
/* Colors and typography aligned with themes/Carbon.less */

@keyframes growProgressBar {
    0%, 33% {
        --pgPercentage: 0;
    }
    100% {
        --pgPercentage: calc((var(--value) - var(--min)) / (var(--max) - var(--min)) * 100);
    }
}

@property --pgPercentage {
    syntax: '<number>';
    inherits: true;
    initial-value: 0;
}

.process-circle-container {
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 1rem;
}

.process-circle {
    /* CSS Custom Properties */
    --size: 0.5rem; /* Ring thickness */
    --circle-size: 12rem; /* Overall circle size */
    --min: 0;
    --max: 100;
    --value: 0;
    --pgPercentage: 0;

    /* Carbon Design System Colors */
    --color-success: #198038; /* @bpm-color-success - Green for 0-50% */
    --color-warning: #f1c21b; /* @bpm-color-warning - Yellow for 50-70% */
    --color-error: #da1e28; /* @bpm-color-alert - Red for 70-100% */
    --color-bg: #e0e0e0; /* Gray 20 - Background ring */
    --color-text: #161616; /* @bpm-text-color - Gray 100 */

    /* Layout */
    width: var(--circle-size);
    height: var(--circle-size);
    border-radius: 50%;
    display: grid;
    place-items: center;
    position: relative;

    /* Background ring */
    background: radial-gradient(
        farthest-side,
        transparent calc(100% - var(--size)),
        var(--color-bg) 0
    );

    /* Typography - Carbon Design System */
    font-family: 'IBM Plex Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif; /* @bpm-font-family-sans-serif */
    font-size: 24px; /* @bpm-font-size-xlarge */
    font-weight: 600; /* @bpm-font-weight-semibold */
    color: var(--color-text);

    /* Animation */
    animation: growProgressBar 2s ease-out forwards;
}

/* Progress ring */
.process-circle::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: 50%;
    padding: var(--size);

    /* Dynamic color based on percentage thresholds */
    background:
        /* Red for >= 70% */
        linear-gradient(var(--color-error) 0 0) 0/calc((var(--pgPercentage) - 70) * 1px) 100%,
        /* Yellow for >= 50% */
        linear-gradient(var(--color-warning) 0 0) 0/calc((var(--pgPercentage) - 50) * 1px) 100%,
        /* Green for < 50% */
        var(--color-success);

    /* Conic gradient mask for circular progress */
    --_mask:
        conic-gradient(#000 calc(var(--pgPercentage) * 1%), transparent 0),
        linear-gradient(#000 0 0) content-box;
    -webkit-mask: var(--_mask);
    mask: var(--_mask);
    -webkit-mask-composite: source-out;
    mask-composite: subtract;
}

/* Center text display */
.process-circle::before {
    content: attr(aria-valuenow) attr(data-post);
    position: relative;
    z-index: 1;
    text-align: center;
}

/* Responsive sizing for smaller screens */
@media (max-width: 768px) {
    .process-circle {
        --circle-size: 10rem;
        font-size: 20px; /* @bpm-font-size-large */
    }
}

@media (max-width: 480px) {
    .process-circle {
        --circle-size: 8rem;
        font-size: 18px; /* @bpm-font-size-large */
    }
}
